<script setup>
import {computed,nextTick,reactive,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import WbAttributeInput from './WbAttributeInput.vue';
import WbListingVariantEditor from './WbListingVariantEditor.vue';
import {wbListingVariants,wbNewVariant,wbGeneratedVendorCode,wbApplyCommon} from '../../../../src/shared/wb-listing-variants.js';
const props=defineProps({shopId:{type:Number,default:null},shops:{type:Array,default:()=>[]},schema:{type:Object,required:true},templates:{type:Array,default:()=>[]},draft:{type:Object,default:null},card:{type:Object,default:null}}),emit=defineEmits(['saved','shop-changed','upload-state']);
const clone=v=>JSON.parse(JSON.stringify(v)),initial=props.draft?.payload||{card:props.card||{title:'',vendorCode:'',brand:'',description:'',dimensions:{length:null,width:null,height:null,weightBrutto:null},characteristics:clone(props.schema.defaults?.characteristics||[]),sizes:[{techSize:'0',price:null,skus:[]}]},images:(props.card?.photos||[]).map(p=>p.big).filter(Boolean)};
const rows=ref(wbListingVariants(initial).map(clone)),shop=ref(props.draft?.target_shop_id||props.draft?.shop_id||props.shopId||null),savedShop=ref(props.draft?.shop_id||props.shopId||null),draftId=ref(props.draft?.id||null),revision=ref(props.draft?.revision||1),strategy=ref(initial.strategy||'grouped'),busy=ref(false),uploading=ref(0),active=ref(null),details=ref(null),preview=ref(false),errors=ref([]),commonLimit=ref(12),source=reactive({query:'',rows:[]});
const attributes=computed(()=>props.schema.attributes.filter(a=>!a.existNamedField&&Number(a.charcType)!==0)),commonFields=computed(()=>attributes.value.filter(a=>a.isVariable!==true)),visibleCommon=computed(()=>[...commonFields.value.filter(a=>a.required),...commonFields.value.filter(a=>!a.required).slice(0,commonLimit.value)]),variableFields=computed(()=>attributes.value.filter(a=>a.isVariable===true));
const common=reactive(Object.fromEntries((rows.value[0]?.card.characteristics||[]).filter(v=>commonFields.value.some(a=>Number(a.charcID)===Number(v.id))).map(v=>[v.id,clone(v.value)])));
function commonValues(){return commonFields.value.map(a=>({id:a.charcID,value:Number(a.charcType)===4?common[a.charcID]===undefined||common[a.charcID]===null||common[a.charcID]===''?undefined:Number(common[a.charcID]):Array.isArray(common[a.charcID])?clone(common[a.charcID]):String(common[a.charcID]||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)})).filter(v=>v.value!==undefined&&(!Array.isArray(v.value)||v.value.length));}
function flush(){if(active.value!==null&&details.value)rows.value[active.value]=details.value.getPayload();}
function payload(){flush();const variants=clone(rows.value);wbApplyCommon(variants,commonValues(),attributes.value);return {...clone(initial),currency:'CNY',strategy:strategy.value,template_id:Number(props.schema.template_id),subject_id:Number(props.schema.subject_id),variants,card:variants[0]?.card||{},images:variants[0]?.images||[],video_url:variants[0]?.video_url||''};}
function generate(row,index){if(row.card.nmID||draftId.value&&index===0)return;row.card.vendorCode=wbGeneratedVendorCode({brand:row.card.brand,subjectId:props.schema.subject_id,shopId:shop.value,index,random:crypto.randomUUID().replaceAll('-','').slice(0,10).toUpperCase()});}
function generateAll(){rows.value.forEach((row,index)=>{if(!row.card.vendorCode)generate(row,index);});}
function addVariant(){if(rows.value.length>=30)return;const row=wbNewVariant(rows.value[0]);generate(row,rows.value.length);rows.value.push(row);}
async function edit(index){if(uploading.value)return;flush();active.value=null;await nextTick();active.value=index;}
function closeDetails(done){if(uploading.value)return;flush();active.value=null;if(typeof done==='function')done();}
function sameFirst(key){for(const row of rows.value.slice(1))row.card[key]=clone(rows.value[0].card[key]);}
function copyMedia(){for(const row of rows.value.slice(1)){row.images=clone(rows.value[0].images);row.video_url=rows.value[0].video_url||'';row.video_source_image=rows.value[0].video_source_image||'';}}
function remove(index){if(rows.value.length===1||draftId.value&&index===0)return;rows.value.splice(index,1);}
async function run(work){if(busy.value||uploading.value)return;busy.value=true;const scope=currentApiCacheScope();try{await work(scope);}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{busy.value=false;}}
async function findSource(){await run(async scope=>{const r=await apiClient.get(`/api/listing/drafts?paged=1&lightweight=1&pageSize=20&query=${encodeURIComponent(source.query)}`,{noCache:true});if(scope===currentApiCacheScope())source.rows=r.rows||[];});}
async function importSource(id){await run(async scope=>{const r=await apiClient.get(`/api/wb/listing-source?source_draft_id=${id}${shop.value?`&shop_id=${shop.value}`:''}`,{noCache:true});if(scope!==currentApiCacheScope())return;rows.value=wbListingVariants(r).map(clone);for(const key of Object.keys(common))delete common[key];for(const value of props.schema.defaults?.characteristics||[])common[value.id]=clone(value.value);source.rows=[];generateAll();});}
async function save(){if(!shop.value)throw Error('上架店铺：请在顶部选择目标 WB 店铺，再保存草稿。');generateAll();let saveId=draftId.value;if(saveId&&Number(savedShop.value)!==Number(shop.value)){await ElMessageBox.confirm('将保存为目标店铺的新草稿，原店铺草稿保留。','保存新店铺草稿');saveId=null;}const r=await apiClient.post('/api/wb/listing-drafts/save',{shop_id:shop.value,draft_id:saveId,revision:revision.value,payload:payload()});draftId.value=r.draft_id;revision.value=r.revision;savedShop.value=shop.value;emit('saved');}
async function saveOnly(){await run(async()=>{await save();ElMessage.success('WB 草稿已保存，未提交上架');});}
async function validate(){preview.value=true;errors.value=[];await run(async scope=>{const r=await apiClient.post('/api/wb/listing-preview',{shop_id:shop.value,payload:payload()});if(scope===currentApiCacheScope())errors.value=r.errors||[];});}
function uploadingChanged(value){uploading.value=value;emit('upload-state',value);}
function attributeValue(row,attribute){return row.card.characteristics?.find(v=>Number(v.id)===Number(attribute.charcID))?.value;}
function updateAttribute(row,attribute,value){row.card.characteristics=(row.card.characteristics||[]).filter(v=>Number(v.id)!==Number(attribute.charcID));row.card.characteristics.push({id:attribute.charcID,value:Number(attribute.charcType)===4?value:Array.isArray(value)?value:String(value||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)});}
function sameAttribute(attribute){const value=attributeValue(rows.value[0],attribute);for(const row of rows.value.slice(1))updateAttribute(row,attribute,value===undefined?'':clone(value));}
defineExpose({getPayload:payload,getShopId:()=>shop.value,getContext:()=>({id:draftId.value,revision:revision.value,shop_id:savedShop.value,target_shop_id:shop.value,payload:payload()}),saveDraft:saveOnly,preview:validate,reviewSubmission:validate});
</script>
<template>
 <div class="wb-workbench-fields">
  <el-form inline class="workbench-settings" :disabled="busy||uploading>0"><el-form-item label="上架店铺" required><el-select v-model="shop" placeholder="选择 WB 店铺" @change="id=>{if(shops.find(s=>Number(s.id)===Number(id))?.environment!==schema.environment)emit('shop-changed');}"><el-option v-for="s in shops" :key="s.id" :value="Number(s.id)" :label="s.name"/></el-select></el-form-item><el-form-item label="变体策略"><el-select v-model="strategy"><el-option label="合并为多变体商品" value="grouped"/><el-option label="各变体独立商品" value="independent"/></el-select></el-form-item></el-form>
  <section v-if="!draftId" class="editor-block source-bar"><el-input v-model="source.query" placeholder="引用已有草稿：输入货号或名称" @keyup.enter="findSource"/><el-button :loading="busy" @click="findSource">搜索草稿</el-button><el-table v-if="source.rows.length" :data="source.rows"><el-table-column prop="internal_code" label="货号"/><el-table-column prop="product_name" label="商品"/><el-table-column width="80"><template #default="{row}"><el-button link @click="importSource(row.id)">引用</el-button></template></el-table-column></el-table></section>
  <section class="editor-block"><div class="section-line"><h3>商品变体</h3><div><el-button :disabled="busy||uploading>0" @click="generateAll">一键生成货号</el-button><el-button :disabled="busy||uploading>0" @click="copyMedia">图片视频同首行</el-button><el-button type="primary" :disabled="rows.length>=30||busy||uploading>0" @click="addVariant">添加变体</el-button></div></div>
   <el-table :data="rows" border stripe class="variant-table dense-variant-table" :scrollbar-always-on="true">
    <el-table-column type="index" label="序号" width="60" fixed="left"/>
    <el-table-column label="商品图片 / 视频" width="140" fixed="left"><template #default="{row,$index}"><el-image v-if="row.images.length" :src="row.images[0]" :preview-src-list="row.images" preview-teleported fit="cover" class="row-image"/><div v-else class="row-image empty-image">无图</div><el-button link type="primary" @click="edit($index)">素材 · {{row.images.length}} 图{{row.video_url?' / 视频':''}}</el-button></template></el-table-column>
    <el-table-column width="240"><template #header><span>商家货号</span></template><template #default="{row,$index}"><el-input v-model="row.card.vendorCode" :disabled="!!row.card.nmID||!!draftId&&$index===0" maxlength="72"/><el-button link :disabled="!!row.card.nmID||!!draftId&&$index===0" @click="generate(row,$index)">生成货号</el-button></template></el-table-column>
    <el-table-column width="260"><template #header>商品标题 <el-button link @click="sameFirst('title')">同首行</el-button></template><template #default="{row}"><el-input v-model="row.card.title" type="textarea" :rows="3" maxlength="60" show-word-limit/></template></el-table-column>
    <el-table-column width="150"><template #header>品牌 <el-button link @click="sameFirst('brand')">同首行</el-button></template><template #default="{row}"><el-input v-model="row.card.brand"/></template></el-table-column>
    <el-table-column v-for="attribute in variableFields" :key="attribute.charcID" width="210"><template #header>{{attribute.name}} <el-button link @click="sameAttribute(attribute)">同首行</el-button></template><template #default="{row}"><WbAttributeInput :model-value="attributeValue(row,attribute)" :attribute="attribute" :subject-id="Number(schema.subject_id)" :shop-id="shop" @update:model-value="updateAttribute(row,attribute,$event)"/></template></el-table-column>
    <el-table-column label="规格与售价（CNY）" width="210"><template #default="{row,$index}"><el-input-number v-model="row.card.sizes[0].price" :min="1" :precision="0" :controls="false"/><div><el-button link @click="edit($index)">{{row.card.sizes.length}} 个尺码 · 编辑条码</el-button></div></template></el-table-column>
    <el-table-column min-width="260"><template #header>商品描述 <el-button link @click="sameFirst('description')">同首行</el-button></template><template #default="{row}"><el-input v-model="row.card.description" type="textarea" :rows="3"/></template></el-table-column>
    <el-table-column width="190"><template #header>包装尺寸 / 重量 <el-button link @click="sameFirst('dimensions')">同首行</el-button></template><template #default="{row,$index}"><div>{{row.card.dimensions.length||'—'}} × {{row.card.dimensions.width||'—'}} × {{row.card.dimensions.height||'—'}} cm</div><div>{{row.card.dimensions.weightBrutto??'—'}} kg</div><el-button link @click="edit($index)">编辑包装</el-button></template></el-table-column>
    <el-table-column label="操作" width="110" fixed="right"><template #default="{$index}"><el-button link type="primary" @click="edit($index)">编辑</el-button><el-button link type="danger" :disabled="rows.length===1||!!draftId&&$index===0" @click="remove($index)">删除</el-button></template></el-table-column>
   </el-table>
  </section>
  <section class="editor-block common-section"><h3>共用属性</h3><el-form label-width="140px" class="common-grid"><el-form-item v-for="attribute in visibleCommon" :key="attribute.charcID" :label="attribute.name" :required="attribute.required"><WbAttributeInput v-model="common[attribute.charcID]" :attribute="attribute" :subject-id="Number(schema.subject_id)" :shop-id="shop"/></el-form-item></el-form><el-button v-if="commonLimit<commonFields.length" @click="commonLimit+=12">展开更多选填属性</el-button></section>
  <el-drawer v-if="active!==null" :model-value="true" :title="'编辑变体 '+(active+1)" size="min(1260px,96vw)" :before-close="closeDetails" :close-on-click-modal="false"><WbListingVariantEditor :key="active" ref="details" :shop-id="shop" :shops="shops" :schema="schema" :templates="templates" :draft="{id:active===0?draftId:null,payload:rows[active],shop_id:shop}" @upload-state="uploadingChanged"/><template #footer><el-button type="primary" :disabled="uploading>0" @click="closeDetails">完成编辑</el-button></template></el-drawer>
  <el-drawer v-if="preview" :model-value="true" title="WB 商品预览与校验" size="min(900px,95vw)" @close="preview=false"><el-alert title="仅校验草稿，尚未提交 WB" :closable="false"/><section v-for="(row,index) in rows" :key="index"><h3>{{index+1}}. {{row.card.title||'待填写标题'}}</h3><p>{{row.card.vendorCode}} · {{row.card.sizes.map(s=>'¥ '+(s.price??'待填写')).join(' / ')}} CNY</p><el-image v-for="(image,i) in row.images" :key="image" :src="image" :preview-src-list="row.images" :initial-index="i" preview-teleported fit="cover" class="preview-image"/><video v-if="row.video_url" :src="row.video_url" controls class="preview-video"/></section><el-alert v-for="error in errors" :key="error" :title="error" type="warning" :closable="false"/><el-button type="primary" :loading="busy" @click="saveOnly">保存草稿</el-button></el-drawer>
 </div>
</template>
<style scoped>
.wb-workbench-fields{display:flex;flex-direction:column;gap:16px}.editor-block,.workbench-settings{padding:16px 20px;border:1px solid var(--el-border-color-lighter);border-radius:8px;background:var(--el-bg-color)}.workbench-settings :deep(.el-form-item){margin-bottom:0}.workbench-settings :deep(.el-select){width:240px}.section-line{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.editor-block h3{margin:0 0 14px;font-size:14px}.section-line h3{margin:0}.source-bar{display:flex;gap:8px;flex-wrap:wrap}.source-bar>.el-input{max-width:380px}.row-image{width:64px;height:84px;display:block;border-radius:4px}.empty-image{display:flex;align-items:center;justify-content:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary)}.variant-table :deep(.el-table__header th){background:var(--el-fill-color-light);font-weight:600}.variant-table :deep(.el-table__cell){padding:8px}.variant-table :deep(.el-input-number){width:100%}.common-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.common-grid :deep(.el-form-item__label){height:auto;line-height:20px;min-height:32px;align-items:center;overflow-wrap:anywhere}.common-grid :deep(.el-select){width:100%}.preview-image{width:96px;height:126px;margin:4px}.preview-video{display:block;max-width:100%;max-height:280px}@media(max-width:1100px){.common-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.section-line{flex-wrap:wrap}}@media(max-width:700px){.common-grid{grid-template-columns:1fr}}
</style>
